import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: interFamily } = loadInter();



export type ConstructionOSProps = Record<string, any>;

const ConstructionOS: React.FC<ConstructionOSProps> = ({
  backgroundColor = "#FAF8F5",
  transparentBackground = false,
  durationInSeconds = 11,
  mainTitle = "Every project\nhas two buckets.",
  leftHeader = "PROFIT",
  rightHeader = "RISK",
  plannedProfitLabel = "PLANNED PROFIT",
  plannedProfitValue = 500000,
  riskImpactLabel = "RISK IMPACT",
  grossProfitLabel = "CURRENT INDICATED GROSS PROFIT",
  bottomQuote = "See the risk before it eats the margin.",
  riskItems = [
    { label: "Late Selections", value: 45000 },
    { label: "Schedule Compression", value: 60000 },
    { label: "Scope Omission", value: 35000 },
    { label: "Rework", value: 35000 },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Resolve backgrounds safely to prevent parser issues
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Total frames in composition
  const totalFrames = durationInSeconds * fps;

  // Main Header (Every project has two buckets) animation
  const titleOpacity = interpolate(frame, [10, 35], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const titleYOffset = interpolate(frame, [10, 35], [15, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // T-Chart Lines animations
  const line1ScaleX = interpolate(frame, [totalFrames * 0.12, totalFrames * 0.18], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const centerLineScaleY = interpolate(frame, [totalFrames * 0.15, totalFrames * 0.23], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Column Headers animations
  const headersOpacity = interpolate(frame, [totalFrames * 0.18, totalFrames * 0.25], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Left Column initial values animations
  const plannedProfitOpacity = interpolate(frame, [totalFrames * 0.23, totalFrames * 0.29], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const plannedProfitYOffset = interpolate(frame, [totalFrames * 0.23, totalFrames * 0.29], [15, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Item distribution math (dynamic based on riskItems count)
  const startItemsFrame = totalFrames * 0.30;
  const endItemsFrame = totalFrames * 0.82;
  const seqDuration = endItemsFrame - startItemsFrame;
  const numItems = riskItems.length || 1;
  const itemDuration = seqDuration / numItems;

  // Formatter helper
  const formatCurrency = (val: number) => {
    return "$" + Math.round(val).toLocaleString("en-US", {
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    });
  };

  // Pre-calculate positions to ensure pixel-perfect and mathematically synchronized alignments
  const cardY = (i: number) => {
    const cardAreaStart = height * 0.25;
    const cardAreaEnd = height * 0.83;
    const segmentHeight = (cardAreaEnd - cardAreaStart) / numItems;
    return cardAreaStart + (i + 0.5) * segmentHeight;
  };

  const deductionY = (i: number) => {
    const deductAreaStart = height * 0.35;
    const deductAreaEnd = height * 0.69;
    const segmentHeight = (deductAreaEnd - deductAreaStart) / numItems;
    return deductAreaStart + (i + 0.5) * segmentHeight;
  };

  // Live profit calculation dynamically compiled per frame
  let currentProfit = plannedProfitValue;
  riskItems.forEach((item, index) => {
    const itemStart = startItemsFrame + index * itemDuration;
    const settleStart = itemStart + itemDuration * 0.60;
    const settleEnd = itemStart + itemDuration * 1.0;
    const t = interpolate(frame, [settleStart, settleEnd], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
    const eased = Easing.out(Easing.quad)(t);
    currentProfit -= item.value * eased;
  });

  // Live sum of total risk compiled so far
  const totalRisk = riskItems.reduce((acc, item) => acc + item.value, 0);

  // Bottom elements reveals
  const riskImpactOpacity = interpolate(frame, [totalFrames * 0.82, totalFrames * 0.88], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const riskImpactScale = interpolate(frame, [totalFrames * 0.82, totalFrames * 0.88], [0.95, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const riskImpactLineScale = interpolate(frame, [totalFrames * 0.80, totalFrames * 0.86], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const grossProfitOpacity = interpolate(frame, [totalFrames * 0.85, totalFrames * 0.91], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const grossProfitScale = interpolate(frame, [totalFrames * 0.85, totalFrames * 0.91], [0.95, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const grossProfitLineScale = interpolate(frame, [totalFrames * 0.83, totalFrames * 0.89], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const bottomLineScale = interpolate(frame, [totalFrames * 0.88, totalFrames * 0.94], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const bottomQuoteOpacity = interpolate(frame, [totalFrames * 0.90, totalFrames * 0.96], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        backgroundImage: `
          radial-gradient(circle at 50% 50%, rgba(255,255,255,0.75) 0%, rgba(0,0,0,0) 100%),
          radial-gradient(rgba(0, 0, 0, 0.02) 1.5px, transparent 0)
        `,
        backgroundSize: `100% 100%, 28px 28px`,
        fontFamily: interFamily,
        color: "#111111",
        overflow: "hidden",
        display: "flex",
        flexDirection: "column",
        boxSizing: "border-box",
      }}
    >
      {/* Upper Main Header Block */}
      <div
        style={{
          position: "absolute",
          top: height * 0.05,
          left: 0,
          right: 0,
          textAlign: "center",
          opacity: titleOpacity,
          transform: `translateY(${titleYOffset}px)`,
          transition: "none",
          zIndex: 10,
        }}
      >
        <h1
          style={{
            fontSize: height * 0.038,
            fontWeight: 800,
            color: "#111111",
            margin: 0,
            lineHeight: 1.15,
            whiteSpace: "pre-line",
            letterSpacing: "-0.02em",
          }}
        >
          {mainTitle}
        </h1>
      </div>

      {/* T-CHART DRAWN ELEMENTS */}
      {/* Horizontal Line 1 */}
      <div
        style={{
          position: "absolute",
          top: height * 0.16,
          left: width * 0.05,
          width: width * 0.9,
          height: 2,
          backgroundColor: "#111111",
          transform: `scaleX(${line1ScaleX})`,
          transformOrigin: "center",
          transition: "none",
          zIndex: 5,
        }}
      />

      {/* Column Headers */}
      <div
        style={{
          position: "absolute",
          top: height * 0.18,
          left: 0,
          right: 0,
          display: "flex",
          opacity: headersOpacity,
          transition: "none",
          zIndex: 5,
        }}
      >
        {/* Profit Column Title */}
        <div
          style={{
            width: "50%",
            textAlign: "center",
            fontSize: height * 0.024,
            fontWeight: 900,
            letterSpacing: "0.12em",
            color: "#111111",
          }}
        >
          {leftHeader}
        </div>
        {/* Risk Column Title */}
        <div
          style={{
            width: "50%",
            textAlign: "center",
            fontSize: height * 0.024,
            fontWeight: 900,
            letterSpacing: "0.12em",
            color: "#BA441A",
          }}
        >
          {rightHeader}
        </div>
      </div>

      {/* Horizontal Line 2 */}
      <div
        style={{
          position: "absolute",
          top: height * 0.22,
          left: width * 0.05,
          width: width * 0.9,
          height: 2,
          backgroundColor: "#111111",
          transform: `scaleX(${line1ScaleX})`,
          transformOrigin: "center",
          transition: "none",
          zIndex: 5,
        }}
      />

      {/* Vertical Center Division Line */}
      <div
        style={{
          position: "absolute",
          top: height * 0.16,
          left: width * 0.5,
          width: 2,
          height: height * 0.72,
          backgroundColor: "#111111",
          transform: `scaleY(${centerLineScaleY})`,
          transformOrigin: "top",
          transition: "none",
          zIndex: 5,
        }}
      />

      {/* LEFT COLUMN: PROFIT STRUCTURE */}
      {/* Planned Profit Metric */}
      <div
        style={{
          position: "absolute",
          top: height * 0.27,
          left: width * 0.25,
          width: width * 0.4,
          transform: `translate(-50%, -50%) translateY(${plannedProfitYOffset}px)`,
          opacity: plannedProfitOpacity,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          transition: "none",
        }}
      >
        <div
          style={{
            color: "#555555",
            fontSize: height * 0.012,
            letterSpacing: "0.08em",
            fontWeight: 700,
            textAlign: "center",
            marginBottom: 2,
          }}
        >
          {plannedProfitLabel}
        </div>
        <div
          style={{
            color: "#111111",
            fontSize: height * 0.040,
            fontWeight: 800,
            textAlign: "center",
            lineHeight: 1,
          }}
        >
          {formatCurrency(plannedProfitValue)}
        </div>
      </div>

      {/* Left Column Dynamic Risk Deductions list */}
      {riskItems.map((item, index) => {
        const itemStart = startItemsFrame + index * itemDuration;
        const settleStart = itemStart + itemDuration * 0.60;
        const settleEnd = itemStart + itemDuration * 1.0;

        // Deduction is faded and stamped in on left
        const opacity = interpolate(frame, [settleStart, settleEnd], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });
        const scale = interpolate(frame, [settleStart, settleEnd], [0.92, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });

        const dY = deductionY(index);

        return (
          <div
            key={`deduct-${index}`}
            style={{
              position: "absolute",
              top: dY,
              left: width * 0.25,
              width: width * 0.4,
              transform: `translate(-50%, -50%) scale(${scale})`,
              opacity,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "center",
              transition: "none",
              zIndex: 10,
            }}
          >
            {/* Dashed line above each sequential item row to guide the eye */}
            {index > 0 && (
              <div
                style={{
                  width: "100%",
                  borderTop: "1.5px dashed #CCCCCC",
                  marginBottom: height * 0.012,
                  transition: "none",
                }}
              />
            )}
            <div
              style={{
                color: "#BA441A",
                fontSize: height * 0.024,
                fontWeight: 800,
                textAlign: "center",
                lineHeight: 1,
              }}
            >
              -{formatCurrency(item.value)}
            </div>
            <div
              style={{
                color: "#555555",
                fontSize: height * 0.013,
                fontWeight: 600,
                textAlign: "center",
                marginTop: 4,
                transition: "none",
                lineHeight: 1.1,
              }}
            >
              {item.label}
            </div>
          </div>
        );
      })}

      {/* Cumulative Risk Impact Segment */}
      <div
        style={{
          position: "absolute",
          top: height * 0.73,
          left: width * 0.25,
          width: width * 0.4,
          transform: `translate(-50%, -50%) scale(${riskImpactScale})`,
          opacity: riskImpactOpacity,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          transition: "none",
        }}
      >
        <div
          style={{
            width: "100%",
            borderTop: "2px solid #111111",
            transform: `scaleX(${riskImpactLineScale})`,
            transformOrigin: "center",
            marginBottom: height * 0.012,
            transition: "none",
          }}
        />
        <div
          style={{
            color: "#555555",
            fontSize: height * 0.012,
            letterSpacing: "0.08em",
            fontWeight: 700,
            textAlign: "center",
            marginBottom: 2,
          }}
        >
          {riskImpactLabel}
        </div>
        <div
          style={{
            color: "#BA441A",
            fontSize: height * 0.026,
            fontWeight: 800,
            textAlign: "center",
            lineHeight: 1,
          }}
        >
          -{formatCurrency(totalRisk)}
        </div>
      </div>

      {/* Final Current Indicated Gross Profit Segment */}
      <div
        style={{
          position: "absolute",
          top: height * 0.81,
          left: width * 0.25,
          width: width * 0.4,
          transform: `translate(-50%, -50%) scale(${grossProfitScale})`,
          opacity: grossProfitOpacity,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          transition: "none",
        }}
      >
        <div
          style={{
            width: "100%",
            borderTop: "2px solid #111111",
            transform: `scaleX(${grossProfitLineScale})`,
            transformOrigin: "center",
            marginBottom: height * 0.012,
            transition: "none",
          }}
        />
        <div
          style={{
            color: "#111111",
            fontSize: height * 0.012,
            letterSpacing: "0.08em",
            fontWeight: 700,
            textAlign: "center",
            marginBottom: 2,
          }}
        >
          {grossProfitLabel}
        </div>
        <div
          style={{
            color: "#111111",
            fontSize: height * 0.040,
            fontWeight: 900,
            textAlign: "center",
            lineHeight: 1,
          }}
        >
          {formatCurrency(currentProfit)}
        </div>
      </div>

      {/* RIGHT COLUMN: RISK STRUCTURE */}
      {riskItems.map((item, index) => {
        const itemStart = startItemsFrame + index * itemDuration;

        // Card reveal animation on Right Column
        const opacity = interpolate(frame, [itemStart, itemStart + itemDuration * 0.25], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });
        const scale = interpolate(frame, [itemStart, itemStart + itemDuration * 0.25], [0.95, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });
        const translateX = interpolate(frame, [itemStart, itemStart + itemDuration * 0.25], [15, 0], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });

        const cY = cardY(index);

        return (
          <div
            key={`card-${index}`}
            style={{
              position: "absolute",
              top: cY,
              left: width * 0.75,
              width: width * 0.4,
              height: height * 0.11,
              transform: `translate(-50%, -50%) scale(${scale}) translateX(${translateX}px)`,
              opacity,
              border: "2px solid #BA441A",
              borderRadius: 12,
              backgroundColor: "#FFFFFF",
              boxShadow: "0 4px 12px rgba(0,0,0,0.03)",
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "center",
              boxSizing: "border-box",
              padding: height * 0.01,
              transition: "none",
              zIndex: 10,
            }}
          >
            <div
              style={{
                color: "#111111",
                fontSize: height * 0.015,
                fontWeight: 700,
                textAlign: "center",
                marginBottom: 4,
                lineHeight: 1.1,
              }}
            >
              {item.label}
            </div>
            <div
              style={{
                color: "#BA441A",
                fontSize: height * 0.026,
                fontWeight: 800,
                textAlign: "center",
                lineHeight: 1,
              }}
            >
              {formatCurrency(item.value)}
            </div>
          </div>
        );
      })}

      {/* FLYING "GHOST" SLIDER VALUE FLOW */}
      {riskItems.map((item, index) => {
        const itemStart = startItemsFrame + index * itemDuration;
        const slideStart = itemStart + itemDuration * 0.25;
        const slideEnd = itemStart + itemDuration * 0.70;

        // Ensure rendering is fully bounded to frame active window
        if (frame < slideStart || frame > slideEnd) {
          return null;
        }

        const t = (frame - slideStart) / (slideEnd - slideStart);
        const easedT = Easing.inOut(Easing.quad)(t);

        // Interpolated trajectory path from Right card center to Left deduction center
        const x = interpolate(easedT, [0, 1], [width * 0.75, width * 0.25]);
        const y = interpolate(easedT, [0, 1], [cardY(index), deductionY(index)]);

        // Subtle opacity peaks exactly in mid-flight and elegantly curves down at terminals
        const opacity = interpolate(t, [0, 0.15, 0.85, 1.0], [0, 1, 1, 0], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });

        return (
          <div
            key={`slider-${index}`}
            style={{
              position: "absolute",
              left: x,
              top: y,
              transform: "translate(-50%, -50%)",
              opacity,
              zIndex: 100,
              pointerEvents: "none",
              textAlign: "center",
              transition: "none",
            }}
          >
            <div
              style={{
                color: "#BA441A",
                fontSize: height * 0.024,
                fontWeight: 800,
                background: "#FFFFFF",
                padding: `${height * 0.01}px ${height * 0.02}px`,
                borderRadius: 8,
                border: "2px dashed #BA441A",
                boxShadow: "0 10px 25px rgba(0,0,0,0.08)",
                whiteSpace: "nowrap",
              }}
            >
              -{formatCurrency(item.value)}
            </div>
          </div>
        );
      })}

      {/* BOTTOM SEGMENT BLOCK */}
      {/* Upper line */}
      <div
        style={{
          position: "absolute",
          top: height * 0.895,
          left: width * 0.05,
          width: width * 0.9,
          height: 1.5,
          backgroundColor: "#111111",
          transform: `scaleX(${bottomLineScale})`,
          transformOrigin: "center",
          transition: "none",
          zIndex: 5,
        }}
      />
      {/* Premium quote caption */}
      <div
        style={{
          position: "absolute",
          top: height * 0.92,
          left: width * 0.5,
          width: width * 0.9,
          transform: "translate(-50%, -50%)",
          opacity: bottomQuoteOpacity,
          textAlign: "center",
          color: "#111111",
          fontSize: height * 0.016,
          fontWeight: 700,
          transition: "none",
          zIndex: 5,
        }}
      >
        {bottomQuote}
      </div>
      {/* Lower line */}
      <div
        style={{
          position: "absolute",
          top: height * 0.945,
          left: width * 0.05,
          width: width * 0.9,
          height: 1.5,
          backgroundColor: "#111111",
          transform: `scaleX(${bottomLineScale})`,
          transformOrigin: "center",
          transition: "none",
          zIndex: 5,
        }}
      />
    </AbsoluteFill>
  );
};

export default ConstructionOS;